cpf_match = re.search(r'CPF[-:\s]*([\d]{3}\.[\d]{3}\.[\d]{3}-[\d]{2})', texto)
cpf = cpf_match.group(1) if cpf_match else None

data_match = re.search(r'data do falecimento[-\s]*[a-zA-Z]*[-\s]*([\d]{1,2})[ \/-]*([a-zA-Z]*)[ \/-]*([\d]{4})', texto)
if data_match:
    dia = data_match.group(1).zfill(2)
    meses = {
        'janeiro': '01', 'fevereiro': '02', 'março': '03', 'abril': '04',
        'maio': '05', 'junho': '06', 'julho': '07', 'agosto': '08',
        'setembro': '09', 'outubro': '10', 'novembro': '11', 'dezembro': '12'
    }
    mes_str = data_match.group(2).lower()
    mes = meses.get(mes_str, '00')
    ano = data_match.group(3)
    data_falecimento = f"{dia}/{mes}/{ano}"
else:
    data_falecimento = None

causa_match = re.search(r'Causa da morte[\s\-]*([\s\S]*?)(\n|$)', texto)
